class LibraryManagementSystemSystem_AutoGenerated {
  /*The scheduler counts down the suspension days for users who have overdue books, suspending their borrowing privileges once the suspension period is over.*/
  countDownSuspensionDay(): void {
    /*Definition Start*/
    let overdueUsers: User[] = l({
      logic: () =>
        getRepository(User).filter(
          (u: any) =>
            l({
              logic: () => u.SuspensionDays > 0,
              description: "u.SuspensionDays>0",
            }).build().pass,
        ),
      description: "User.allInstance()->select(u|u.SuspensionDays>0)",
    }).build().pass;
    let overdueBookLoans: Loan[] = l({
      logic: () =>
        getRepository(Loan).filter(
          (_l: any) =>
            l({
              logic: () => _l.OverDueFee > 0,
              description: "l.OverDueFee>0",
            }).build().pass,
        ),
      description: "Loan.allInstance()->select(l|l.OverDueFee>0)",
    }).build().pass;
    let suspendedUsers: User[] = l({
      logic: () =>
        getRepository(User).filter(
          (u: any) =>
            l({
              logic: () => u.BorrowStatus === "SUSPEND",
              description: "u.BorrowStatus='SUSPEND'",
            })
              .or({
                logic: () => u.BorrowStatus === "SUSPEND",
                description: "u.BorrowStatus='SUSPEND'",
              })
              .build().pass,
        ),
      description:
        "User.allInstance()->select(u|u.BorrowStatus='SUSPEND'oru.BorrowStatus='SUSPEND')",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => overdueUsers.length > 0,
        description: "overdueUsers.size()>0",
      })
        .and({
          logic: () =>
            overdueUsers.forEach(
              (u: any) =>
                l({
                  logic: () => u.BorrowStatus === "NORMAL",
                  description: "u.BorrowStatus='NORMAL'",
                })
                  .or({
                    logic: () => u.BorrowStatus === "NORMAL",
                    description: "u.BorrowStatus='NORMAL'",
                  })
                  .build().pass,
            ),
          description:
            "overdueUsers->forAll(u|u.BorrowStatus='NORMAL'oru.BorrowStatus='NORMAL')",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let user: User;
    return l({
      execute: () => (user = new User()),
      description: "user.oclIsNew()",
    })
      .and({
        execute: () => (user.SuspensionDays = user.SuspensionDays - 1),
        description: "user.SuspensionDays=user.SuspensionDays-1",
      })
      .and({
        execute: () => getRepository(User).push(user),
        description: "User.allInstance()->includes(user)",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { LibraryManagementSystemSystem_AutoGenerated };

